/**
 * Device-proven XOR key for Homescapes 9.2.101 `SaveGame.db` containers
 * (the `#f205`-style binary wrappers written by `HS::Services::SaveManagerImpl`).
 *
 * PROVENANCE — how this key was obtained and what it is proven against:
 *   - Source ciphertext: `SaveGame.db` + `.bak` + `.buf` pulled from the live
 *     MEmu emulator (serial 127.0.0.1:21503) while the shipping 9.2.101 client
 *     was running. Nothing on disk was modified to obtain it.
 *   - Recovery: known-plaintext statistical attack. The container is
 *     repeating-key XOR with period 731 (proven by lag correlation: match rate
 *     5.0% at lag 731 and all multiples vs 0.39% baseline; all bytes < 0x80 so
 *     key and plaintext are 7-bit). Each key byte was recovered by maximizing
 *     the log-likelihood of the implied plaintext bytes under a byte-frequency
 *     language model built from the known plain sample save. Decisive margins:
 *     min 1.14 nats/position over ~441 votes per key byte, 0 weak indices.
 *   - Verification (all three device generations, same key):
 *       * `live1.db`   (322,055 B) -> valid JSON, 49 root groups, round-trip exact
 *       * `live1.bak`  (322,055 B) -> valid JSON, round-trip exact
 *       * `live1.buf`  (322,054 B) -> valid JSON, round-trip exact
 *     Content cross-checks the live game HUD: `Properties.coins = 1010`,
 *     `lives.current = 5`, `avatarId = 14` (fresh level-1 account).
 *   - Container shape: plaintext is compact JSON (no CRLF/tab indentation,
 *     unlike the older community sample) followed by a single trailing NUL
 *     byte. XOR starts at file offset 0 — there is no header; the apparent
 *     `#\x10f205` "header" was ciphertext that happens to spell those bytes.
 *
 * Relation to the community key (`xor-key.ts`): only 11 of 731 bytes match.
 * The community key round-trips the older 4.5 MB level-655 sample but fails on
 * every alignment of these 9.2.101 device files, so the key was rotated between
 * versions. Both keys are kept: f205 first (current builds), community as the
 * legacy fallback.
 *
 * NOT verified: whether this key is global for 9.2.101 or per-account — only
 * one account was available. It is stable across save generations of that
 * account (db/bak/buf), which is what editing requires.
 *
 * Generated by G:\hs_build\verify_f205.mjs. Do not hand-edit.
 */

export const F205_KEY_B64 =
  "";
export const F205_KEY_BYTES = 731;
export const F205_KEY_SHA256 = "069ba06a8e6c8d53cd9b27af3e7685fb25959cb5208c38406c256f767b16df89";

let cached: Uint8Array | null = null;

/** Decode the base64 key once and memoize it. Throws if the constant is corrupt. */
export function f205Key(): Uint8Array {
  if (cached) return cached;
  const bin = atob(F205_KEY_B64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  if (out.length !== F205_KEY_BYTES) {
    throw new Error(`f205 key length mismatch: ${out.length} != ${F205_KEY_BYTES}`);
  }
  cached = out;
  return out;
}
